import { MakeLogicType, actions, kea, listeners, path } from 'kea'

import { elementPathsLogic } from '~/toolbar/shared/element-paths/elementPathsLogic'

import type { PageToolbarJourneysState } from '../../messaging/pageToolbarBridge'

export type PageJourneysCommand = { type: 'set-enabled'; enabled: boolean } | { type: 'retry' }

const DISABLED_STATE: PageToolbarJourneysState = { enabled: false, view: { status: 'idle' } }

let lastPageState: PageToolbarJourneysState = DISABLED_STATE

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface extensionPageJourneysLogicValues {}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface extensionPageJourneysLogicActions {
    handleCommand: (command: PageJourneysCommand) => {
        command: PageJourneysCommand
    }
}

export type extensionPageJourneysLogicType = MakeLogicType<
    extensionPageJourneysLogicValues,
    extensionPageJourneysLogicActions
>

/**
 * Runs in the content script. The panel turns the paths on while it shows the journeys section, because the page's
 * copy of the toolbar's posthog-js has no flags, and each selection runs a query.
 */
export const extensionPageJourneysLogic = kea<extensionPageJourneysLogicType>([
    path(['toolbar', 'extension', 'extensionPageJourneysLogic']),
    actions({
        handleCommand: (command: PageJourneysCommand) => ({ command }),
    }),
    listeners(({ cache }) => ({
        handleCommand: ({ command }) => {
            if (command.type === 'retry') {
                elementPathsLogic.findMounted()?.actions.retryElementPaths()
            } else if (command.enabled) {
                if (!elementPathsLogic.findMounted()) {
                    // The panel shows the page that is open, so a hidden tab keeps the paths it loaded.
                    cache.disposables.add(() => elementPathsLogic.mount(), 'elementPaths', { pauseOnPageHidden: false })
                }
            } else {
                cache.disposables.dispose('elementPaths')
            }
        },
    })),
])

/** Keeps the previous object while nothing changed, so the host doesn't post the slice again. */
export function getPageJourneysState(): PageToolbarJourneysState {
    const view = elementPathsLogic.findMounted()?.values.elementPathsView
    const next: PageToolbarJourneysState = view ? { enabled: true, view } : DISABLED_STATE
    if (next.enabled !== lastPageState.enabled || next.view !== lastPageState.view) {
        lastPageState = next
    }
    return lastPageState
}
